This document contains the complete PostgreSQL analysis script executed against the ecommerce_db database.

1. Database Verification & Row Count Auditing
Before performing analysis, table integrity was confirmed across all 8 ingested tables.
```sql SELECT ‘customers’ AS table_name, COUNT() AS total_rows FROM customers UNION ALL SELECT ‘orders’, COUNT() FROM orders UNION ALL SELECT ‘order_items’, COUNT() FROM order_items UNION ALL SELECT ‘products’, COUNT() FROM products UNION ALL SELECT ‘order_payments’, COUNT() FROM order_payments UNION ALL SELECT ‘order_reviews’, COUNT() FROM order_reviews UNION ALL SELECT ‘sellers’, COUNT() FROM sellers UNION ALL SELECT ‘product_category_name_translation’, COUNT() FROM product_category_name_translation;
SELECT COUNT(DISTINCT o.order_id) AS total_orders, ROUND(SUM(i.price), 2) AS total_revenue_usd, ROUND(AVG(i.price), 2) AS avg_item_price FROM orders o JOIN order_items i ON o.order_id = i.order_id WHERE o.order_status = ‘delivered’;
SELECT t.product_category_name_english AS category_name, COUNT(DISTINCT i.order_id) AS total_orders, ROUND(SUM(i.price), 2) AS total_revenue_usd FROM order_items i JOIN products p ON i.product_id = p.product_id JOIN product_category_name_translation t ON p.product_category_name = t.product_category_name GROUP BY t.product_category_name_english ORDER BY total_revenue_usd DESC LIMIT 10;
SELECT payment_type, COUNT(order_id) AS total_transactions, ROUND(SUM(payment_value), 2) AS total_payment_value, ROUND(AVG(payment_installments), 1) AS avg_installments FROM order_payments GROUP BY payment_type ORDER BY total_payment_value DESC;
SELECT DATE_TRUNC(‘month’, o.order_purchase_timestamp)::DATE AS order_month, COUNT(DISTINCT o.order_id) AS total_orders, ROUND(SUM(p.payment_value), 2) AS monthly_revenue FROM orders o JOIN order_payments p ON o.order_id = p.order_id WHERE o.order_status = ‘delivered’ GROUP BY 1 ORDER BY order_month ASC;
SELECT CASE WHEN o.order_delivered_customer_date &gt; o.order_estimated_delivery_date THEN ‘Late’ ELSE ‘On-Time’ END AS delivery_performance, COUNT(DISTINCT o.order_id) AS total_orders, ROUND(AVG(r.review_score), 2) AS avg_review_score FROM orders o JOIN order_reviews r ON o.order_id = r.order_id WHERE o.order_status = ‘delivered’ AND o.order_delivered_customer_date IS NOT NULL GROUP BY 1;
WITH customer_metrics AS ( SELECT c.customer_unique_id, MAX(o.order_purchase_timestamp) AS last_purchase_date, COUNT(DISTINCT o.order_id) AS total_orders, ROUND(SUM(p.payment_value), 2) AS total_spent FROM customers c JOIN orders o ON c.customer_id = o.customer_id JOIN order_payments p ON o.order_id = p.order_id WHERE o.order_status = ‘delivered’ GROUP BY c.customer_unique_id ) SELECT customer_unique_id, total_orders, total_spent, NTILE(4) OVER (ORDER BY total_spent DESC) AS monetary_quartile FROM customer_metrics ORDER BY total_spent DESC LIMIT 10;
